import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"26、【大畜】 乾下艮上","description":"橫渠易說 - 26、【大畜】 乾下艮上","frontmatter":{"title":"26、【大畜】 乾下艮上","description":"橫渠易說 - 26、【大畜】 乾下艮上"},"headers":[],"relativePath":"classics/hengqu/028.md","filePath":"classics/hengqu/028.md"}'),l={name:"classics/hengqu/028.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_26、【大畜】-乾下艮上" tabindex="-1">26、【大畜】 乾下艮上 <a class="header-anchor" href="#_26、【大畜】-乾下艮上" aria-label="Permalink to “26、【大畜】 乾下艮上”">​</a></h1><h3 id="彖曰-大畜-剛健篤實輝光-日新其德。剛上而尚賢-能止健-大正也。-不家食吉-養賢也。-利涉大川-應乎天也。" tabindex="-1">彖曰：大畜，剛健篤實輝光，日新其德。剛上而尚賢，能止健，大正也。“不家食吉”，養賢也。“利涉大川”，應乎天也。 <a class="header-anchor" href="#彖曰-大畜-剛健篤實輝光-日新其德。剛上而尚賢-能止健-大正也。-不家食吉-養賢也。-利涉大川-應乎天也。" aria-label="Permalink to “彖曰：大畜，剛健篤實輝光，日新其德。剛上而尚賢，能止健，大正也。“不家食吉”，養賢也。“利涉大川”，應乎天也。”">​</a></h3><h3 id="象曰-天在山中-大畜-君子以多識前言往行以畜其德。" tabindex="-1">象曰：天在山中，大畜，君子以多識前言往行以畜其德。 <a class="header-anchor" href="#象曰-天在山中-大畜-君子以多識前言往行以畜其德。" aria-label="Permalink to “象曰：天在山中，大畜，君子以多識前言往行以畜其德。”">​</a></h3><p>剛健篤實，日新其德，乃天德也。 陽卦在上，而上九又在其上，故曰“剛上而尚賢”。強學者往往心多好勝，必無心處(一)［之］乃善也。定然後始有光明，惟能定已是光明矣，若常移易不定，何(求)［來］光明!易大抵以艮為止，止乃光明。時止時行，“動靜不失其時，其道光明”，“謙天道下濟而光明”，“天在山中，大畜，君子以剛健篤實輝光，日新其德”，定則自光明，故大學定而至於能慮。人心多則無由光明。(蒙雜而著著古著字雜著於物所以為濛濛昏蒙)</p><h3 id="初九-有厲-利己。-象曰-有厲利己-不犯災也。" tabindex="-1">初九，有厲，利己。 象曰：“有厲利己”，不犯災也。 <a class="header-anchor" href="#初九-有厲-利己。-象曰-有厲利己-不犯災也。" aria-label="Permalink to “初九，有厲，利己。 象曰：“有厲利己”，不犯災也。”">​</a></h3><p>趨其應則有二三之阻，故不若己也。</p><h3 id="九二-輿說輹。-象曰-輿說輹-中無尤也。" tabindex="-1">九二，輿說輹。 象曰：“輿說輹”，中無尤也。 <a class="header-anchor" href="#九二-輿說輹。-象曰-輿說輹-中無尤也。" aria-label="Permalink to “九二，輿說輹。 象曰：“輿說輹”，中無尤也。”">​</a></h3><p>不阻於三則見童於四，不躁進者，位中也。</p><h3 id="九三-良馬逐-利艱貞。曰閒輿衛-利有攸往。-象曰-利有攸往-上合志也。" tabindex="-1">九三，良馬逐，利艱貞。曰閒輿衛，利有攸往。 象曰：“利有攸往”，上合志也。 <a class="header-anchor" href="#九三-良馬逐-利艱貞。曰閒輿衛-利有攸往。-象曰-利有攸往-上合志也。" aria-label="Permalink to “九三，良馬逐，利艱貞。曰閒輿衛，利有攸往。 象曰：“利有攸往”，上合志也。”">​</a></h3><p>不防輿衛而進歷二陰，則或有童牿說(輻)［輹］之害，不利其往也。本乎天者親上，故上合志也。</p><h3 id="六四-童牛之牿-元吉。-象曰-六四元吉-有喜也。" tabindex="-1">六四，童牛之牿，元吉。 象曰：六四元吉，有喜也。 <a class="header-anchor" href="#六四-童牛之牿-元吉。-象曰-六四元吉-有喜也。" aria-label="Permalink to “六四，童牛之牿，元吉。 象曰：六四元吉，有喜也。”">​</a></h3><h3 id="六五-豶豕之牙-吉。-象曰-六五之吉-有慶也。" tabindex="-1">六五，豶豕之牙，吉。 象曰：六五之吉，有慶也。 <a class="header-anchor" href="#六五-豶豕之牙-吉。-象曰-六五之吉-有慶也。" aria-label="Permalink to “六五，豶豕之牙，吉。 象曰：六五之吉，有慶也。”">​</a></h3><h3 id="上九-何天之衢-亨。-象曰-何天之衢-道大行也。" tabindex="-1">上九，何天之衢，亨。 象曰：“何天之衢”，道大行也。 <a class="header-anchor" href="#上九-何天之衢-亨。-象曰-何天之衢-道大行也。" aria-label="Permalink to “上九，何天之衢，亨。 象曰：“何天之衢”，道大行也。”">​</a></h3><p>其道大行也，升於天，何待衢路而進？言無所不通也。衢字當為絕句。艮為止，止二陰也，不以止其類也，故亨。</p>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
